for PJ,QJ in pairs(MJ.evolve and MJ.evolve.normal and MJ.evolve.normal.item_requirement or{})do
local RJ=N.SaleEvent[QJ.item_id]
if RJ and type(RJ.resource_cost)==TNd[1788]and RJ.resource_cost.id==TNd[2416]then
OJ.item,OJ.itemCost=QJ.item_id,tonumber(RJ.resource_cost.amount)or 0
