W._spawns={}
function W.levelSpawns(lL,mL)
local nL=tostring(lL)
local oL=W._spawns[nL]
if oL and os.time()-oL.at<3600 then
return oL.n
end
local pL=0
pcall(function()
local qL=N.Levels[lL]
local rL=fb.info(fb.slim and fb.slim(qL)or qL,TNd[2454]..nL)
local sL=false
for tL,uL in pairs(rL.configs or{})do
if mL[tL]or(type(uL)==TNd[1788]and mL[uL.unit_id or TNd[712]])then
sL=true
break
end
end
if not sL then
return
end
local vL=rL.infinite and math.floor(W.infReach(TNd[1962]..nL)+0.5)or rL.total
local function wL(xL)
local yL=rL.configs[xL]
return mL[xL]or(type(yL)==TNd[1788]and mL[yL.unit_id or TNd[712]])
end
for zL=1,math.min(vL or 30,200)do
if rL.infinite then
local AL,BL=pcall(N.LU.Infinite.infinite_amt_scale,zL,rL.ld)
local CL,DL=0,0
for EL,FL in pairs(rL.configs)do
if type(FL)==TNd[1788]and FL.spawn_tier_normal then
local GL,HL=pcall(N.LU.Infinite.infinite_get_normal_unit_chance,FL,zL)
HL=GL and tonumber(HL)or 0
CL=CL+HL
if wL(EL)then
DL=DL+HL
end
end
end
if CL>0 then
pL=pL+(AL and tonumber(BL)or 10)*DL/CL
end
else
local IL=rL.list[zL]
for JL,KL in ipairs(U.list(IL and IL.wave))do
if wL(KL.unit)then
pL=pL+(tonumber(KL.amount)or 1)
end
end
end
end
pL=math.floor(pL+0.5)
end)
W._spawns[nL]={n=pL,at=os.time()}
return pL
end
function W.missionValue(LL)
local ML=N.session()
local NL,OL=0,nil
for PL,QL in pairs(ML and ML.quest_handler.quest_profile_data.quests or{})do
local RL=QL.quest_info
local SL=RL and RL.quest_class
if SL and SL.class==TNd[2455]and type(SL.unit_ids)==TNd[1788]then
local TL=tonumber(SL.amount)or 0
local UL=TL-(tonumber(QL.quest_progress and QL.quest_progress.amount)or 0)
if UL>0 then
local VL=W.levelSpawns(LL,SL.unit_ids)
if VL>0 then
local WL=tonumber(RL.quest_reward and RL.quest_reward.gem_reward)or 0
for XL,YL in pairs(RL.quest_reward and RL.quest_reward.item or{})do
if type(YL)==TNd[1788]and YL.item_id then
WL=WL+W.itemValue(YL.item_id,tonumber(YL.max_amount or YL.amount or YL.min_amount)or 1)
end
