return(vQ and vQ.limit_break and tonumber(vQ.limit_break.current_limit_break))or 0
end
function jb.share(wQ)
local xQ=P.str.share[wQ]
if xQ and(P.str.shareN or 0)>=3 then
return math.max(0.05,xQ)
end
local yQ,zQ=0,0
for AQ,BQ in ipairs(V.equipped())do
if not V.isFarm(BQ.id)then
local CQ=jb.score(BQ.u)
yQ=yQ+CQ
if BQ.id==wQ then
zQ=CQ
end
end
end
return math.max(0.05,yQ>0 and zQ/yQ or 0.1)
end
function jb.learn(DQ,EQ)
P.str.shareN=(P.str.shareN or 0)+1
local FQ=math.max(0.1,1/P.str.shareN)
for GQ,HQ in ipairs(EQ or{})do
if HQ.id and not V.isFarm(HQ.id)then
local IQ=DQ[HQ.id]or 0
local JQ=P.str.share[HQ.id]
P.str.share[HQ.id]=JQ and(JQ+(IQ-JQ)*FQ)or IQ
end
end
F.saveSoon()
end
function jb.core(KQ,LQ)
local MQ=N.session()
if not MQ then
return P.str.core or{}
end
local NQ={}
if type(P.savedTeam)==TNd[1788]and#P.savedTeam>0 then
for OQ,PQ in ipairs(P.savedTeam)do
local QQ=MQ.collection:get_unit_by_uuid(PQ)
if QQ then
table.insert(NQ,{uuid=PQ,id=QQ.unit_id})
end
end
end
if#NQ==0 then
for RQ,SQ in ipairs(V.equipped())do
table.insert(NQ,{uuid=SQ.uuid,id=SQ.id})
end
end
local TQ={}
for UQ,VQ in ipairs(NQ)do
table.insert(TQ,VQ.uuid)
end
table.sort(TQ)
local WQ=table.concat(TQ,TNd[2497])
if not KQ and#(P.str.core or{})>=6 and os.time()-(tonumber(P.str.coreAt)or 0)<(O.teamCoreDays or 7)*86400 then
if P.str.teamSig==WQ then
return P.str.core
end
if P.str.pendingSig~=WQ then
P.str.pendingSig,P.str.pendingAt=WQ,os.time()
return P.str.core
end
if os.time()-(tonumber(P.str.pendingAt)or 0)<600 then
return P.str.core
end
end
if not LQ then
P.str.pendingSig,P.str.pendingAt=nil,nil
end
local XQ,YQ={},{}
for ZQ,_Q in ipairs(NQ)do
table.insert(XQ,_Q.uuid)
YQ[_Q.id]=true
end
for aR,bR in ipairs({TNd[2498],TNd[2499]})do
local cR=O[bR]
local dR=type(cR)==TNd[698]and cR~=TNd[712]and MQ.collection:get_unit_by_uuid(cR)
if dR and not table.find(XQ,cR)then
table.insert(XQ,cR)
YQ[dR.unit_id]=true
end
end
local eR={}
for fR,gR in pairs(P.simTeam or{})do
if type(gR)==TNd[1788]and os.time()-(tonumber(gR.at)or 0)<7*86400 then
for hR,iR in ipairs(gR.names or{})do
eR[iR]=(eR[iR]or 0)+1
end
end
end
local jR={}
for kR,lR in pairs(MQ.profile_data.collection.owned_units)do
local mR=N.Units[lR.unit_id]
if mR and(mR.rarity==TNd[2083]or mR.rarity==TNd[2500])and not YQ[lR.unit_id]and V.rows(lR.unit_id)and not V.hidden(lR.unit_id)and not V.isFarm(lR.unit_id)and not V.allyBuff(lR.unit_id)then
local nR=MQ.collection:get_unit_by_uuid(kR)or lR
table.insert(jR,{uuid=kR,id=lR.unit_id,k=(eR[V.name(lR.unit_id)]or 0)*1e12+jb.score(nR)})
end
end
table.sort(jR,function(oR,pR)
if oR.k~=pR.k then
return oR.k>pR.k
end
return oR.uuid<pR.uuid
end)
for qR,rR in ipairs(jR)do
if#XQ>=8 then
break
end
if not YQ[rR.id]then
table.insert(XQ,rR.uuid)
YQ[rR.id]=true
end
end
if LQ then
return XQ
end
P.str.core,P.str.coreAt,P.str.teamSig=XQ,os.time(),WQ
local sR={}
for tR,uR in ipairs(XQ)do
local vR=MQ.collection:get_unit_by_uuid(uR)
if vR then
table.insert(sR,V.name(vR.unit_id))
end
end
F.log(1,jb.LOG,TNd[2501]..table.concat(sR,TNd[1899]))
F.saveSoon()
return XQ
end
function jb.gainXp(wR,xR)
local yR,zR=tonumber(wR.xp)or 0,jb.xpFor(wR.unit_id,jb.cap(wR))
local AR=math.max(0,zR-yR)
if AR<=0 or(xR or 0)<=0 then
return 0,0
end
local BR=math.min(xR,AR)
local CR=jb.base(wR)
if CR<=0 then
return 0,BR
end
return jb.share(wR.unit_id)*(jb.score(jb.whatIf(wR,{xp=yR+BR}))/CR-1)*100,BR
end
jb.MAX_RELICS=6
jb.RELIC_MOVE_GAIN=0.5
jb.RELIC_SETTLED_GAIN=2
jb.RELIC_STOP_GAIN=5
function jb.relicBar()
if P.str.relicTeam==nil or P.str.relicTeam==W.teamSig()then
return jb.RELIC_SETTLED_GAIN
end
return jb.RELIC_MOVE_GAIN
end
function jb.relicWorth(DR,ER)
local FR=ER._unique_item_data and ER._unique_item_data._unique_relic_data
if not FR then
return 0
end
local GR=N.Items[ER.item_id]or{}
local HR,IR=V.types(DR.unit_id)
if GR.main_damage_type and GR.main_damage_type~=TNd[2502]and GR.main_damage_type~=IR then
return 0
end
local JR,KR=0,0
for LR,MR in pairs(FR._core_damage_type_buffs or{})do
if HR[MR.damage_type]then
JR=JR+(tonumber(MR.mul)or 0)+(tonumber(MR.add_upg)or 0)*0.01+(tonumber(MR.pen)or 0)*0.001
KR=KR+(tonumber(MR.crit)or 0)
end
end
JR=JR+KR*0.5
local NR=V.rows(DR.unit_id)
local OR=NR and NR[NR.max]
local PR=(OR and tonumber(OR.cd)or 0)*V.mult(DR,TNd[1953])
for QR,RR in pairs(FR._unique_relic_effects or{})do
local SR=type(RR.params)==TNd[1788]and RR.params or{}
if RR.id==TNd[2503]then
local TR=math.min(1,(tonumber(SR.extra_damage)or 0)*PR/math.max(1,tonumber(SR.time_interval)or 40))
local UR=V.DRONES and V.DRONES[DR.unit_id]
if UR and UR.late and PR>0 then
local VR=1/PR
TR=TR*VR/(VR+(tonumber(UR.max)or 0)*(tonumber(UR.late.dmg)or 0)*(tonumber(UR.hits)or 1)/math.max(0.1,tonumber(UR.late.cd)or 4))
end
JR=JR+TR
elseif RR.id==TNd[2504]then
JR=JR+(tonumber(SR.dmg_buff)or 0)*0.25
elseif RR.id==TNd[2505]then
JR=JR+(tonumber(SR.dmg_buff)or 0)*KR
elseif RR.id==TNd[2506]then
if HR.magic then
JR=0
else
JR=JR+(tonumber(SR.dmg_buff)or 0)*0.3
end
elseif RR.id==TNd[2507]then
if HR.water_damage then
JR=JR+0.05
end
end
end
return JR
end
function jb.relicPlan()
local WR=N.session()
if not WR then
return nil
end
local XR=WR.inventory and WR.inventory.inventory_profile_data or{}
local YR={}
for ZR,_R in ipairs(XR.unique_items or{})do
if type(_R)==TNd[1788]and _R.uuid and(N.Items[_R.item_id]or{}).item_group==TNd[2508]then
table.insert(YR,_R)
end
end
local aS={}
for bS,cS in ipairs(V.equipped())do
local dS=cS.data and cS.data.rarity
if not V.isFarm(cS.id)and(dS==TNd[2082]or dS==TNd[2083]or dS==TNd[2500]or dS==TNd[2509])then
local eS=jb.share(cS.id)
if not P.str.share[cS.id]then
eS=math.min(eS,0.15)
end
local fS={}
for gS,hS in ipairs(YR)do
local iS=jb.relicWorth(cS.u,hS)*eS*100
if iS>0.01 then
table.insert(fS,{it=hS,w=iS})
end
end
table.sort(fS,function(jS,kS)
if jS.w~=kS.w then
return jS.w>kS.w
end
return jS.it.uuid<kS.it.uuid
end)
local lS,mS={},{}
for nS,oS in ipairs(fS)do
local pS=mS[oS.it.item_id]or 0
if#lS<6 and pS<((N.Items[oS.it.item_id]or{}).unique_equip and 1 or 2)then
mS[oS.it.item_id]=pS+1
table.insert(lS,oS)
end
end
if cS.u._equipped_relic then
local qS=false
for rS,sS in ipairs(lS)do
if sS.it.uuid==cS.u._equipped_relic then
qS=true
end
end
local tS=not qS and WR.inventory:get_item_by_uuid(cS.u._equipped_relic)
if tS then
table.insert(lS,{it=tS,w=jb.relicWorth(cS.u,tS)*eS*100})
end
end
table.insert(aS,{e=cS,share=eS,opts=lS})
end
end
local uS,vS={},-1
local wS,xS,yS={},{},{}
local function zS(AS,BS)
if AS> #aS then
if BS>vS then
vS=BS
uS=table.clone(wS)
end
return
end
local CS=aS[AS]
wS[CS.e.uuid]=nil
zS(AS+1,BS)
for DS,ES in ipairs(CS.opts)do
local FS=(N.Items[ES.it.item_id]or{}).unique_equip
if not xS[ES.it.uuid]and not(FS and yS[ES.it.item_id])then
xS[ES.it.uuid]=true
if FS then
yS[ES.it.item_id]=true
end
wS[CS.e.uuid]=ES.it.uuid
zS(AS+1,BS+ES.w+(ES.it.uuid==CS.e.u._equipped_relic and 0.01 or 0))
wS[CS.e.uuid]=nil
xS[ES.it.uuid]=nil
if FS then
yS[ES.it.item_id]=nil
end
end
end
end
zS(1,0)
local HS,IS=0,{}
for JS,KS in ipairs(aS)do
local LS=KS.e.u._equipped_relic and WR.inventory:get_item_by_uuid(KS.e.u._equipped_relic)
local MS=LS and jb.relicWorth(KS.e.u,LS)*KS.share*100 or 0
HS=HS+MS
local NS=uS[KS.e.uuid]and WR.inventory:get_item_by_uuid(uS[KS.e.uuid])
local OS=NS and jb.relicWorth(KS.e.u,NS)*KS.share*100 or 0
table.insert(IS,string.format(TNd[2510],V.name(KS.e.id),LS and(N.Items[LS.item_id]or{}).name or TNd[2093],MS,NS and(N.Items[NS.item_id]or{}).name or TNd[2093],OS))
end
return uS,vS-HS,IS,aS
end
function jb.relicsApply(PS)
if not(O.team and O.teamRelics)or O.strDry then
return false
end
local QS=W.teamSig()
if not PS and P.str.relicSig==QS and os.time()-(tonumber(P.str.relicAt)or 0)<600 then
return false
end
if F.req.back.relicMove and U.now()<F.req.back.relicMove then
return false
end
P.str.relicSig,P.str.relicAt=QS,os.time()
local RS,TS,US,VS=jb.relicPlan()
if not RS then
return false
end
P.str.relicNote=string.format(TNd[2511],math.max(0,TS))
if TS<jb.relicBar()then
P.str.relicTeam=QS
return false
end
local WS=N.session()
local XS=WS.profile_data.collection.owned_units
local function YS(ZS)
for _S,aT in pairs(XS)do
if aT._equipped_relic==ZS then
return _S,aT
end
end
end
local function bT(cT)
return F.gameSaid(cT)or TNd[2106]
end
local function dT(eT)
local fT,gT=YS(eT)
if not fT then
return true
end
local hT=U.now()
F.request(TNd[2512],TNd[2513],eT)
while U.now()-hT<4 and gT._equipped_relic==eT do
task.wait(0.25)
end
task.wait(1.2)
if gT._equipped_relic==eT then
F.log(1,TNd[2493],string.format(TNd[2514],V.name(gT.unit_id),tostring(V.relicName(gT)),bT(hT)))
F.backoff(TNd[2512],300)
return false
end
return true
end
F.log(1,TNd[2493],string.format(TNd[2515],TS,table.concat(US,TNd[2019])))
for iT,jT in ipairs(VS)do
local kT=jT.e.u._equipped_relic
if kT and kT~=RS[jT.e.uuid]and not dT(kT)then
return false
end
end
for lT,mT in pairs(RS)do
local nT=YS(mT)
if nT and nT~=lT and not dT(mT)then
return false
end
end
table.sort(VS,function(oT,pT)
return oT.share>pT.share
end)
local qT=0
for rT,sT in ipairs(VS)do
local tT=RS[sT.e.uuid]
if tT and sT.e.u._equipped_relic~=tT then
local uT,vT=0,nil
local wT={}
for xT,yT in ipairs(V.equipped())do
wT[yT.uuid]=true
end
for zT,AT in pairs(XS)do
if AT._equipped_relic then
uT=uT+1
if not wT[zT]and(not vT or not table.find(P.str.core or{},zT))then
vT=AT._equipped_relic
end
end
end
if uT>=jb.MAX_RELICS and vT and not dT(vT)then
return false
end
local BT=U.now()
F.request(TNd[2512],TNd[2048],tT,{unit_uuid=sT.e.uuid})
while U.now()-BT<4 and sT.e.u._equipped_relic~=tT do
task.wait(0.25)
end
task.wait(1.2)
if sT.e.u._equipped_relic~=tT then
F.log(1,TNd[2493],string.format(TNd[2516],(N.Items[(WS.inventory:get_item_by_uuid(tT)or{}).item_id]or{}).name or TNd[2517],V.name(sT.e.id),bT(BT)))
F.backoff(TNd[2512],300)
P.str.relicAt=0
return false
end
qT=qT+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
P.str.relicTeam=P.str.relicSig
P.str.relicNote=string.format(TNd[2518],TS)
jb.note(string.format(TNd[2519],qT,TS))
return true
end
function jb.foodHeld()
