for GT,HT in pairs(FT.normal_items or{})do
local IT=N.Items[GT]
if type(IT)==TNd[1788]and type(IT.usage)==TNd[1788]and IT.usage.type==TNd[2520]and(tonumber(HT)or 0)>0 then
table.insert(ET,{id=GT,n=tonumber(HT),xp=tonumber(IT.usage.xp_amount)or 0})
