function jb.plan()
local RT=N.session()
if not RT then
return{}
end
local TT={}
local UT=jb.core()
local VT=jb.foodHeld()
local WT=0
for XT,YT in ipairs(VT)do
WT=WT+YT.n*YT.xp
end
for ZT,_T in ipairs(UT)do
local aU=RT.collection:get_unit_by_uuid(_T)
if aU then
local bU,cU=aU.unit_id,V.name(aU.unit_id)
if O.teamXp and WT>0 then
local dU,eU=jb.gainXp(aU,WT)
local fU,gU=jb.gainXp(aU,500000)
local hU=gU>0 and fU/gU*eU or 0
if eU>0 and hU>0 then
local iU=jb.feedPlan(aU)
local jU,kU=jb.level(aU),jb.level({unit_id=bU,xp=(tonumber(aU.xp)or 0)+eU})
table.insert(TT,{kind=TNd[2521],uuid=_T,name=cU,gain=hU,add=eU,planned=iU.planned,items=iU.n,lvl0=jU,lvl1=jb.level({unit_id=bU,xp=(tonumber(aU.xp)or 0)+(iU.planned>0 and iU.planned or eU)}),text=string.format(TNd[2522],cU,U.fmt(eU),kU>jU and string.format(TNd[2523],jU,kU)or string.format(TNd[2524],jU),hU)})
end
end
end
end
table.sort(TT,function(lU,mU)
if lU.gain~=mU.gain then
return lU.gain>mU.gain
end
return lU.text<mU.text
end)
for nU in pairs(V._mult)do
if type(nU)==TNd[698]and nU:sub(1,5)==TNd[2496]then
V._mult[nU]=nil
end
end
P.str.acts,P.str.actsAt={},os.time()
for oU=1,math.min(12,#TT)do
local pU=TT[oU]
table.insert(P.str.acts,{kind=pU.kind,uuid=pU.uuid,name=pU.name,gain=pU.gain,text=pU.text,blocked=pU.blocked,add=pU.add,planned=pU.planned,items=pU.items,lvl0=pU.lvl0,lvl1=pU.lvl1})
end
return TT
end
function jb.xpRate()
local qU=N.session()
if not qU then
return 0
end
local rU=0
for sU,tU in ipairs(jb.core())do
local uU=qU.collection:get_unit_by_uuid(tU)
if uU then
local vU,wU=jb.gainXp(uU,500000)
if wU>0 then
rU=math.max(rU,vU/wU)
end
end
end
local xU=rU*(O.strengthValue or 300)
if(tonumber(N.cur(TNd[1853]))or 0)>(O.xpGoldFloor or 100000)then
xU=math.min(xU,(N.GOLD_VALUE or 0.02)/14)
end
return xU
end
function jb.xpGuess(yU)
local zU=yU.level and N.Levels[yU.level]
if not zU then
return 0
end
local AU=math.min(9,tonumber(zU.story_world_rank)or tonumber(yU.rank)or 9)
local BU=tonumber(zU.story_level_rank)or 6
local CU=(yU.kind==TNd[1827]and 1.5 or 1)*(AU>5 and 2 or 1)
local DU=2.1564^(AU-1)*(40+10*BU)/CU
if yU.kind==TNd[1807]then
DU=3*30*2.1564^(AU-1)/CU
end
local EU=AU>=9 and 0.3 or(AU>=7 and 0.5 or 1)
return DU*EU*6
end
function jb.modeBonus(FU)
if not(O.team and O.teamXp)or FU.kind==TNd[1808]or FU.kind==TNd[1805]then
return 0
end
local GU=jb._xpRate and os.time()-(jb._xpRateAt or 0)<300 and jb._xpRate or nil
if not GU then
GU=jb.xpRate()
jb._xpRate,jb._xpRateAt=GU,os.time()
end
if GU<=0 then
return 0
end
local HU=P.modes and P.modes[FU.key]
local IU=tonumber(HU and HU.xp)or jb.xpGuess(FU)
local JU=IU*GU
if JU<1 then
return 0
end
return JU,string.format(TNd[2525],U.fmt(IU),math.floor(JU+0.5))
end
function jb.xpSettle()
local KU=P.lastRun
if not(KU and type(KU.xp0)==TNd[1788]and KU.key)then
return
end
local MU=N.session()
if not MU then
return
end
local NU,OU=0,0
for PU,QU in pairs(KU.xp0)do
local RU=MU.collection:get_unit_by_uuid(PU)
if RU then
NU=NU+math.max(0,(tonumber(RU.xp)or 0)-(tonumber(QU)or 0))
OU=OU+1
end
end
P.lastRun=nil
if OU==0 then
return
end
local SU=W.rec(KU.key)
SU.xp=SU.xp and(SU.xp+(NU-SU.xp)*0.3)or NU
if NU>0 then
F.log(2,jb.LOG,string.format(TNd[2526],KU.key,U.fmt(NU)))
end
F.saveSoon()
end
function jb.note(TU)
F.log(1,jb.LOG,TU)
table.insert(P.str.log,1,{at=os.time(),msg=TU})
while#P.str.log>20 do
table.remove(P.str.log)
end
F.saveSoon()
