function jb.feedPlan(UU)
local VU=V.trait(UU)
local WU=VU==TNd[2527]and 1.5 or 1
local XU=math.max(0,jb.xpFor(UU.unit_id,jb.cap(UU))-(tonumber(UU.xp)or 0))
local YU,ZU,_U={},0,0
for aV,bV in ipairs(jb.foodHeld())do
local cV=bV.xp*WU
local dV=math.min(bV.n,math.floor((XU-ZU)/math.max(1,cV)))
if dV>0 then
YU[bV.id]=dV
ZU=ZU+dV*cV
_U=_U+dV
end
end
return{feed=YU,planned=ZU,n=_U}
end
function jb.run(eV)
local fV=N.session()
local gV=fV and fV.collection:get_unit_by_uuid(eV.uuid)
if not gV then
return
end
if eV.kind==TNd[2521]then
local hV=jb.feedPlan(gV)
local iV,jV,kV=hV.feed,hV.planned,hV.n
if kV==0 then
P.str.feedNote=eV.name..TNd[2528]
return
end
local lV,mV=tonumber(gV.xp)or 0,jb.level(gV)
local nV,oV=F.request(TNd[2521],TNd[2529],eV.uuid,iV)
local pV=U.now()
while U.now()-pV<4 and(tonumber((fV.collection:get_unit_by_uuid(eV.uuid)or gV).xp)or 0)<=lV do
task.wait(0.25)
end
local qV=fV.collection:get_unit_by_uuid(eV.uuid)or gV
local rV=(tonumber(qV.xp)or 0)-lV
if rV>0 then
local sV=jb.level(qV)
local tV=sV>mV and string.format(TNd[2523],mV,sV)or string.format(TNd[2524],mV)
