local TX=ab.FUSE_RANK[O.fuseXpRarity]or 2
local UX={[RX.uuid]=true,[O.evolveUnit]=true}
for VX,WX in ipairs(V.equipped())do
UX[WX.uuid]=true
end
for XX,YX in ipairs(P.savedTeam or{})do
UX[YX]=true
end
for ZX,_X in ipairs(P.train and P.train.on and P.train.on.base or{})do
UX[_X]=true
end
local aY,bY={},0
for cY,dY in pairs(SX.profile_data.collection.owned_units)do
local eY=N.Units[dY.unit_id]
local fY=eY and ab.FUSE_RANK[eY.rarity]
if fY and fY<=TX and not UX[cY]then
local gY=SX.collection:get_unit_by_uuid(cY)or dY
if not(dY._locked or gY._locked)and not(dY._equipped_relic or gY._equipped_relic)then
local hY,iY=pcall(N.USC.calculate_xp_gain_from_fuse,RX,{gY},SX)
iY=hY and tonumber(iY)or 0
if iY>0 then
table.insert(aY,{uuid=cY,id=dY.unit_id,xp=iY,rarity=eY.rarity})
bY=bY+iY
end
end
end
end
table.sort(aY,function(jY,kY)
if jY.xp~=kY.xp then
return jY.xp<kY.xp
end
return jY.uuid<kY.uuid
end)
local lY=math.max(0,jb.xpFor(RX.unit_id,jb.cap(RX))-(tonumber(RX.xp)or 0))
local mY,nY={},0
for oY,pY in ipairs(aY)do
