table.insert(Ycb,{uuid=_cb,u=adb,kind=bdb.item_id,relic=adb._equipped_relic,k=(Vcb[_cb]and 1e12 or 0)+jb.score(adb)})
end
end
table.sort(Ycb,function(cdb,ddb)
if cdb.k~=ddb.k then
return cdb.k>ddb.k
end
return cdb.uuid<ddb.uuid
end)
local edb={}
