ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=24*3600}
function ab.unitEvidence(Meb)
local Neb=P.learn[Meb]
local Oeb=Neb and tonumber(Neb.n)or 0
local Peb=db.hive()
local Qeb=Peb and type(Peb.units)==TNd[1788]and Peb.units[Meb]
if type(Qeb)==TNd[1788]then
Oeb=Oeb+(tonumber(Qeb.matches)or 0)+(tonumber(Qeb.matches3)or 0)
end
return Oeb
end
function ab.unitLabSafe(Reb)
if O.unitLab==false or type(Reb)~=TNd[1788]or not ab.LAB.KINDS[Reb.kind]or Reb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==TNd[1788]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=TNd[715]then
return false
end
local Seb,Teb=pcall(ab.matchOn,Reb)
if Seb and Teb then
return false
end
local Ueb=type(P.unitLab)==TNd[1788]and P.unitLab or{}
if Ueb.pauseKey==Reb.key and os.time()<(tonumber(Ueb.pauseUntil)or 0)then
return false
end
local Veb=W.rec(Reb.key)
local Web,Xeb=tonumber(Veb.runs)or 0,tonumber(Veb.wins)or 0
if Reb.kind==TNd[1807]then
local Yeb,Zeb=pcall(W.infDaily,N.prof(),Reb.level,W.infReach(Reb.key))
return Web>=3 and Yeb and(tonumber(Zeb)or 1)<=0
end
return Web>=5 and(tonumber(Veb.streak)or 0)==0 and Xeb/Web>=0.9
end
function ab.unitLab(_eb)
if not ab.unitLabSafe(_eb)then
return
end
P.unitLab=type(P.unitLab)==TNd[1788]and P.unitLab or{}
local afb=P.unitLab
afb.tried=type(afb.tried)==TNd[1788]and afb.tried or{}
afb.seen=(tonumber(afb.seen)or 0)+1
if afb.seen%ab.LAB.EVERY~=0 then
return
end
local bfb=N.session()
local cfb=V.equipped()
if not bfb or#cfb<2 then
return
end
local dfb={}
for efb,ffb in ipairs(cfb)do
dfb[ffb.uuid]=true
dfb[ffb.id]=true
end
local gfb,hfb,ifb
for jfb,kfb in pairs(bfb.profile_data.collection.owned_units)do
local lfb=kfb.unit_id
if not dfb[jfb]and not dfb[lfb]and N.Units[lfb]and not V.isFarm(lfb)and not V.allyBuff(lfb)and os.time()-(tonumber(afb.tried[lfb])or 0)>ab.LAB.AGAIN then
local mfb=ab.unitEvidence(lfb)
if mfb<ab.LAB.MIN_EVIDENCE then
local nfb=bfb.collection:get_unit_by_uuid(jfb)or kfb
local ofb=jb.score(nfb)
if ofb>0 and(not gfb or mfb<hfb or(mfb==hfb and ofb>ifb))then
gfb,hfb,ifb={uuid=jfb,id=lfb,u=nfb},mfb,ofb
end
end
end
end
if not gfb then
return
end
local pfb,qfb
for rfb,sfb in ipairs(cfb)do
if not V.isFarm(sfb.id)and not V.allyBuff(sfb.id)and sfb.uuid~=O.evolveUnit then
local tfb=jb.score(sfb.u)
if not pfb or tfb<qfb then
pfb,qfb=sfb,tfb
end
end
end
if not pfb then
return
end
afb.tried[gfb.id]=os.time()
local ufb=0
for vfb in pairs(afb.tried)do
ufb=ufb+1
if ufb>300 then
afb.tried[vfb]=nil
end
end
local wfb,xfb=fb.levelFor(_eb)
if not wfb then
return
end
local yfb=fb.info(wfb,_eb.key,xfb,_eb.mod or W.ldMod(wfb)or W.levelMod(_eb.level))
local zfb={}
for Afb,Bfb in ipairs(cfb)do
table.insert(zfb,Bfb.uuid==pfb.uuid and gfb.u or Bfb.u)
end
local Cfb,Dfb=pcall(fb.run,yfb,fb.teamFrom(zfb,yfb.map),{hpMul=1.1})
local Efb=Cfb and type(Dfb)==TNd[1788]and(Dfb.won or(yfb.infinite and(tonumber(Dfb.wave)or 0)>=0.8*W.infReach(_eb.key)))
if not Efb then
F.log(2,TNd[3017],string.format(TNd[3018],V.name(gfb.id),_eb.label))
return
end
local Ffb={}
for Gfb,Hfb in ipairs(cfb)do
table.insert(Ffb,Hfb.uuid==pfb.uuid and gfb.uuid or Hfb.uuid)
end
if ab.equipTeam(Ffb,TNd[3019]..V.name(gfb.id))then
afb.now={id=gfb.id,out=pfb.id,key=_eb.key,at=os.time(),ev=hfb}
F.log(1,TNd[3017],string.format(TNd[3020],V.name(gfb.id),V.name(pfb.id),_eb.label,hfb))
F.saveNow()
end
end
