ab.QUICK_SEARCH=7
function ab.teamFor(Sfb,Tfb)
if Sfb.key==TNd[2232]then
if P.savedTeam then
ab.restoreTeam()
end
return
end
local Ufb=N.session()
local Vfb=P.testTeam
if Vfb and(Vfb.left or 0)>0 and Vfb.key==Sfb.key and type(Vfb.uuids)==TNd[1788]then
local Wfb=0
for Xfb,Yfb in ipairs(Vfb.uuids)do
if Ufb.collection:get_unit_by_uuid(Yfb)then
Wfb=Wfb+1
end
end
if Wfb== #Vfb.uuids then
if P.train.on then
hb.home()
end
if not hb.same(hb.team(),Vfb.uuids)then
ab.equipTeam(Vfb.uuids,TNd[3030]..tostring(Vfb.label))
end
return
end
end
if O.dailyLoop and Sfb.kind==TNd[1969]and type(O.dailyTeam)==TNd[1788]and#O.dailyTeam>0 then
local Zfb,_fb={},{}
for agb,bgb in ipairs(P.savedTeam or hb.team())do
local cgb=Ufb.collection:get_unit_by_uuid(bgb)
if cgb then
_fb[cgb.unit_id]=bgb
end
end
for dgb,egb in ipairs(O.dailyTeam)do
local fgb,ggb=_fb[egb],nil
if not fgb then
local hgb,igb=V.isFarm(egb),V.rows(egb)
for jgb,kgb in pairs(Ufb.profile_data.collection.owned_units)do
if kgb.unit_id==egb then
local lgb=Ufb.collection:get_unit_by_uuid(kgb.uuid)or kgb
local mgb,ngb
if hgb then
mgb,ngb=pcall(V.farm,lgb,igb and igb.max or 0)
else
mgb,ngb=pcall(V.score,lgb)
end
ngb=mgb and ngb or 0
if not ggb or ngb>ggb then
fgb,ggb=kgb.uuid,ngb
end
end
end
end
if fgb then
table.insert(Zfb,fgb)
end
end
if#Zfb== #O.dailyTeam then
if P.train.on then
hb.home()
end
if not hb.same(hb.team(),Zfb)then
ab.equipTeam(Zfb,TNd[3031])
end
