function eb.upgradeGain(pjb,qjb,rjb,sjb,tjb,ujb)
local vjb,wjb=qjb[rjb],qjb[rjb+1]
local xjb=(vjb.cd>0 and vjb.damage/vjb.cd or 0)
local yjb=(wjb.cd>0 and wjb.damage/wjb.cd or 0)*V.aoe(wjb.atk,wjb.range)/math.max(0.3,V.aoe(vjb.atk,vjb.range))
local zjb=xjb>0 and pjb*(yjb/xjb-1)or(ujb or 0)
local Ajb=qjb[rjb+2]
if Ajb and rjb+1<qjb.max and Ajb.cd>0 and wjb.cd>0 and xjb>0 then
local Bjb=pjb*((Ajb.damage/Ajb.cd)/xjb-1)
local Cjb=sjb+Ajb.cost*tjb
if Bjb/Cjb>zjb/sjb then
zjb=zjb+(Bjb/Cjb*sjb-zjb)*0.5
end
end
local Djb=(wjb.range or 0)>(vjb.range or 0)and(1+((wjb.range-vjb.range)/math.max(1,vjb.range)))or 1
return math.max(0,zjb)*Djb
end
function eb.dpsFor(Ejb,Fjb)
if Fjb<=0 then
return 0
end
local Gjb={}
for Hjb,Ijb in ipairs(Ejb)do
if not Ijb.farm and Ijb.gain>0 then
table.insert(Gjb,Ijb)
end
end
table.sort(Gjb,function(Jjb,Kjb)
return Jjb.gain/Jjb.cost>Kjb.gain/Kjb.cost
end)
local Ljb,Mjb=0,0
for Njb,Ojb in ipairs(Gjb)do
if Fjb<=0 then
break
end
Mjb=Ojb.gain/Ojb.cost
local Pjb=math.min(1,Fjb/Ojb.cost)
Ljb=Ljb+Ojb.gain*Pjb
Fjb=Fjb-Ojb.cost*Pjb
end
return Ljb+math.max(0,Fjb)*Mjb*0.7
end
function eb.shieldDps(Qjb,Rjb,Sjb,Tjb,Ujb,Vjb,Wjb)
if(Tjb or 0)<=0 or(Qjb or 0)<=0 or(Ujb or 0)<=0 then
return Qjb or 0
end
Rjb,Sjb,Vjb=math.max(0.3,Rjb or 2),math.max(1,Sjb or 1),Vjb or 1
local Xjb=Qjb*Vjb*Rjb/Sjb
return Ujb*Sjb/((Tjb/math.max(1,Wjb or 1)+math.max(1,Ujb/Xjb))*Rjb)/Vjb
end
function eb.shieldGain(Yjb,Zjb,_jb,akb,bkb,ckb,dkb,ekb)
local fkb,gkb=V.attackInfo(Zjb.atk,Zjb.range),V.attackInfo(akb.atk,akb.range)
local hkb=eb.shieldDps(Yjb,(tonumber(Zjb.cd)or 2)*(dkb or 1),fkb.n,bkb,ckb,ekb,fkb.hits)
local ikb=eb.shieldDps(_jb,(tonumber(akb.cd)or 2)*(dkb or 1),gkb.n,bkb,ckb,ekb,gkb.hits)
