fb.DMG_SOLVE_LO,fb.DMG_SOLVE_HI,fb.DMG_SOLVE_TRIES=0.1,3,6
function fb.dmgSolve(lub,mub,nub,oub,pub)
local function qub(rub)
local tub=table.clone(lub)
tub.dmgMul,tub._dk=rub,nil
local uub,vub=pcall(fb.runRaw,tub,mub,nub)
if not(uub and type(vub)==TNd[1788])then
