for jwb,kwb in ipairs(dwb)do
if not kwb.farm and not hwb[kwb.id]then
local lwb=(tonumber(ewb.dealt[V.name(kwb.id)])or 0)+((V.DRONES and V.DRONES[kwb.id])and(tonumber(ewb.dealt.drones)or 0)or 0)
hwb[kwb.id]={e=kwb,d=lwb}
iwb=iwb+lwb
