table.insert(Iwb,Kwb.t)
end
local Lwb,Mwb=pcall(bb.label)
F.log(1,TNd[3189],string.format(TNd[3190],tostring(Lwb and Mwb or bb.key),nwb and TNd[3186]or TNd[3187],table.concat(Iwb,TNd[2019])))
