local BTb,CTb
for DTb,ETb in ipairs(ib.after(nTb,zTb.choice))do
local FTb=ib.roomValue(ETb,qTb)
if not BTb or FTb>BTb then
BTb,CTb=FTb,ETb
end
end
local GTb,HTb=ib.winP(zTb)
