function bb.layoutAdd(lkc,mkc,nkc,okc,pkc)
lkc.runs,lkc.wins=(tonumber(lkc.runs)or 0)+1,(tonumber(lkc.wins)or 0)+(mkc and 1 or 0)
lkc.sec,lkc.wave=type(lkc.sec)==TNd[1788]and lkc.sec or{},type(lkc.wave)==TNd[1788]and lkc.wave or{}
if mkc and tonumber(nkc)then
table.insert(lkc.sec,math.floor(nkc+0.5))
end
table.insert(lkc.wave,tonumber(okc)or 0)
if tonumber(pkc)then
lkc.kills=type(lkc.kills)==TNd[1788]and lkc.kills or{}
table.insert(lkc.kills,math.floor(tonumber(pkc)))
while#lkc.kills>bb.LAYOUT_KEEP do
table.remove(lkc.kills,1)
end
end
while#lkc.sec>bb.LAYOUT_KEEP do
table.remove(lkc.sec,1)
end
while#lkc.wave>bb.LAYOUT_KEEP do
table.remove(lkc.wave,1)
end
end
function bb.layoutJudge(qkc,rkc,skc,tkc)
local ukc,vkc=tonumber(qkc and qkc.runs)or 0,tonumber(rkc and rkc.runs)or 0
if ukc<1 or vkc<bb.LAYOUT_CONTROL then
return nil
end
if tkc and type(qkc.kills)==TNd[1788]and type(rkc.kills)==TNd[1788]and#qkc.kills>=1 and#rkc.kills>=bb.LAYOUT_CONTROL then
local wkc,xkc=bb.labMedian(qkc.kills),bb.labMedian(rkc.kills)
if wkc and xkc and wkc<xkc*0.97 and(#qkc.kills>=2 or wkc<xkc*0.85)then
return string.format(TNd[3699],wkc,xkc)
end
return nil
end
local ykc,zkc=(tonumber(qkc.wins)or 0)/ukc,(tonumber(rkc.wins)or 0)/vkc
if not skc and zkc>=0.5 then
if ykc+0.25<zkc and(ukc>=2 or(ykc==0 and zkc>=0.9 and vkc>=3))then
return string.format(TNd[3700],tonumber(qkc.wins)or 0,ukc,ukc==1 and TNd[712]or TNd[1636],tonumber(rkc.wins)or 0,vkc)
end
local Akc,Bkc=bb.labMedian(qkc.sec),bb.labMedian(rkc.sec)
if Akc and Bkc and Akc>Bkc*1.10 and(#qkc.sec>=2 or Akc>Bkc*1.25)then
return string.format(TNd[3701],math.floor(Akc/60),Akc%60,math.floor(Bkc/60),Bkc%60)
end
return nil
end
local Ckc,Dkc=bb.labMedian(qkc.wave),bb.labMedian(rkc.wave)
if Ckc and Dkc and Ckc<Dkc-math.max(1,Dkc*0.03)and(ukc>=2 or Ckc<Dkc*0.85)then
return string.format(TNd[3702],Ckc,Dkc)
end
return nil
end
