bb.CONTROL_WORDS={TNd[3705],TNd[3706],TNd[3707],TNd[3708]}
function bb.controlSpot(Rkc,Skc)
if not bb.killZone()then
return nil
end
local Tkc=fb.holds
if not Tkc(Rkc.id)or V.toggleOf(Rkc.id)then
return nil
end
local Ukc,Vkc,Wkc,Xkc=1,0,0,{}
for Ykc,Zkc in ipairs(bb.mine or{})do
local _kc=Zkc._stats
local alc=_kc.id.Value
if _kc:FindFirstChild(TNd[1955])and not V.isFarm(alc)and not V.allyBuff(alc)then
local blc,clc=U.flat(Zkc:GetPivot().Position),_kc.range.Value
if Tkc(alc)and not V.toggleOf(alc)then
Wkc=Wkc+1
table.insert(Xkc,{p=blc,r=clc})
else
for dlc,elc in ipairs(bb.samples)do
if(U.flat(elc.pos)-blc).Magnitude<=clc then
Ukc,Vkc=math.min(Ukc,elc.prog),math.max(Vkc,elc.prog)
end
end
end
end
end
if Vkc<=Ukc then
Ukc,Vkc=0.75,0.98
end
local flc=(Skc or Wkc)+1
local glc=({Ukc,Vkc,(Ukc+Vkc)/2,Ukc-(Vkc-Ukc)/2})[flc]
if not glc then
return nil
end
local hlc=V.range(Rkc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local ilc={}
for jlc,klc in ipairs(bb.cands)do
local llc,mlc,nlc=U.flat(klc),0,0
for olc,plc in ipairs(bb.samples)do
if(U.flat(plc.pos)-llc).Magnitude<=hlc then
nlc=nlc+1
if math.abs(plc.prog-glc)<=0.05 then
mlc=mlc+1
local qlc=U.flat(plc.pos)
for rlc,slc in ipairs(Xkc)do
if(qlc-slc.p).Magnitude<=slc.r then
mlc=mlc-0.5
break
end
end
end
end
end
if mlc>0 then
table.insert(ilc,{pos=klc,sc=mlc,cov=nlc})
end
if jlc%60==0 then
task.wait()
end
end
table.sort(ilc,function(tlc,ulc)
return tlc.sc>ulc.sc
end)
for vlc,wlc in ipairs(ilc)do
local xlc=bb.valid(wlc.pos,Rkc.data)
if xlc then
F.log(1,TNd[3629],string.format(TNd[3709],V.name(Rkc.id),bb.CONTROL_WORDS[flc],math.floor(glc*100+0.5)))
return xlc,wlc.cov,glc
end
if vlc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(ylc)
local zlc,Alc=fb.holds(ylc.id)
