local Flc=Elc._stats
local Glc=Flc.id.Value
if Flc:FindFirstChild(TNd[1955])and not V.isFarm(Glc)and not V.allyBuff(Glc)and Glc~=ylc.id then
local Hlc,Ilc=pcall(bb.liveDps,Elc,Glc)
Ilc=Hlc and tonumber(Ilc)or 0
if Ilc>0 then
table.insert(Blc,{p=U.flat(Elc:GetPivot().Position),r=Flc.range.Value,d=Ilc})
Clc=Clc+Ilc
end
end
end
if#Blc==0 or Clc<=0 then
return nil
end
local Jlc={}
for Klc,Llc in ipairs(bb.samples)do
local Mlc,Nlc=U.flat(Llc.pos),0
for Olc,Plc in ipairs(Blc)do
if(Mlc-Plc.p).Magnitude<=Plc.r then
Nlc=Nlc+Plc.d
end
end
Jlc[Klc]=Nlc/Clc
end
local Qlc=V.range(ylc.u,math.min(tonumber(Alc)or 0,3,V.rows(ylc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Rlc,Slc,Tlc
for Ulc,Vlc in ipairs(bb.cands)do
local Wlc,Xlc,Ylc=U.flat(Vlc),0,0
for Zlc,_lc in ipairs(bb.samples)do
if(U.flat(_lc.pos)-Wlc).Magnitude<=Qlc then
Xlc=Xlc+Jlc[Zlc]
Ylc=Ylc+1
end
end
if Xlc>0 and(not Slc or Xlc>Slc)then
local amc=bb.valid(Vlc,ylc.data)
if amc then
Rlc,Slc,Tlc=amc,Xlc,Ylc
end
