local Ymc=(bb.kind==TNd[1808]or bb.style==TNd[3168]or bb.style==TNd[3169])and not cmc and not(Nmc and Nmc.leak)and not V.isFarm(bmc.id)and V.range(bmc.u,V.rows(bmc.id).max)*Wmc or nil
local Zmc=V.allyBuff(bmc.id)
