local Mnc=bb.infinite and bb.trainee and not dmc and bmc.uuid~=bb.trainee and not V.isFarm(bmc.id)and not Zmc and not cmc and not(Nmc and Nmc.leak)and(bb.pressure or 0)<O.dangerReach and hb.ZONE or nil
local Nnc=Mnc and V.range(bmc.u,V.rows(bmc.id).max)or nil
