end
local aoc=cmc and not Znc and bb.random and V.isFarm(bmc.id)and bb.farmMergeOk()and{}or nil
local boc=bb.cands
local coc,doc=Znc or Xnc,Znc and _nc or Ync
if coc and doc and doc>0 then
boc=table.clone(bb.cands)
for eoc,foc in ipairs({0.5,0.7,0.9})do
