function bb.lookAt(Uoc)
local Voc,Woc=math.huge,nil
for Xoc,Yoc in ipairs(bb.samples)do
local Zoc=(U.flat(Yoc.pos)-U.flat(Uoc)).Magnitude
if Zoc<Voc then
Voc,Woc=Zoc,Yoc.pos
end
end
local _oc=Woc and U.flat(Woc-Uoc)or Vector3 .new(0,0,-1)
return _oc.Magnitude>0.01 and _oc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(apc,bpc)
local cpc=V.isFarm(apc.id)
local dpc,epc=bb.bestSpot(apc,cpc or(bb.random and V.idol(apc.id)),(bb.trainee~=nil and apc.uuid==bb.trainee)or V.ENTRY[apc.id]==true or(bb.studyEntry==true and apc.id==bb.trialId))
if not dpc then
bb.noSpot[apc.uuid]=(bb.noSpot[apc.uuid]or 0)+1
F.status(TNd[3623],TNd[3712]..V.name(apc.id))
return false
end
local fpc=bb.money()
local gpc=P.caps[apc.uuid]and bb.count(apc.uuid)or nil
local hpc,ipc=F.request(TNd[3713],TNd[3714],apc.uuid,N.Util.CFramePLV(dpc,bb.lookAt(dpc)))
if hpc and ipc then
if gpc and gpc>=(tonumber(P.caps[apc.uuid])or math.huge)then
F.log(1,TNd[3629],string.format(TNd[3715],V.name(apc.id),tostring(P.caps[apc.uuid])))
P.caps[apc.uuid],P.capsAt[apc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(apc.data.cost or 0)
table.insert(bb.actions,string.format(TNd[3716],V.name(apc.id)))
F.log(1,TNd[3629],string.format(TNd[3717],V.name(apc.id),bb.spotKey(dpc),epc,bpc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=apc.id,x=math.floor(dpc.X),z=math.floor(dpc.Z),cover=math.floor((epc or 0)+0.5),why=tostring(bpc):sub(1,90)})
F.status(TNd[3623],string.format(TNd[3718],V.name(apc.id),bpc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[apc.uuid]=(bb.placedAt[apc.uuid]or 0)+1
return true
end
if fpc>=(apc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[apc.uuid]=(bb.placeFail[apc.uuid]or 0)+1
if bb.placeFail[apc.uuid]>=2 then
bb.noSpot[apc.uuid]=3
F.log(1,TNd[3629],string.format(TNd[3719],V.name(apc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if hpc and fpc>=(apc.data.cost or 0)and not bb.random then
local jpc=bb.spotKey(dpc)
bb.refused[jpc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[apc.uuid]=(bb.unitRefusals[apc.uuid]or 0)+1
if not bb.crowded()then
local kpc=bb.mapKey()
P.blocked[kpc]=P.blocked[kpc]or{}
if not bb.refusedRun[jpc]then
P.blocked[kpc][jpc]=(tonumber(P.blocked[kpc][jpc])or 0)+1
bb.refusedRun[jpc]=true
end
if bb.unitRefusals[apc.uuid]>=3 then
local lpc=math.max(1,bb.count(apc.uuid))
if P.caps[apc.uuid]~=lpc or not V.learnedCap(apc.uuid)then
P.caps[apc.uuid],P.capsAt[apc.uuid]=lpc,os.time()
F.log(1,TNd[3629],string.format(TNd[3720],V.name(apc.id),lpc))
end
end
elseif bb.unitRefusals[apc.uuid]>=3 and(bb.noSpot[apc.uuid]or 0)<3 then
bb.noSpot[apc.uuid]=3
F.log(1,TNd[3629],string.format(TNd[3721],V.name(apc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,TNd[3629],string.format(TNd[3722],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,TNd[3629],TNd[3723]..jpc..TNd[2435]..V.name(apc.id))
F.saveSoon()
end
return false
end
