if not tpc.start and xpc>0 and#bb.mine==0 then
tpc.start=xpc
end
if wpc~=tpc.lastW then
if bb.trialId and wpc>0 then
bb.trialTrace=bb.trialTrace or{}
local ypc,zpc,Apc,Bpc=0,{},0,0
for Cpc,Dpc in ipairs(bb.mine)do
local Epc=Dpc._stats
if Epc.id.Value==bb.trialId then
ypc=ypc+1
table.insert(zpc,tostring(Epc.upgrade.Value))
elseif not V.isFarm(Epc.id.Value)then
Bpc=Bpc+1
end
end
pcall(bb.sampleHelpers,true)
for Fpc,Gpc in pairs(bb.ownDealt)do
if Gpc.id==bb.trialId then
Apc=Apc+Gpc.v
end
end
local Hpc=0
for Ipc,Jpc in pairs(bb.helperDealt)do
if Jpc.owner==bb.trialId then
Hpc=Hpc+Jpc.v
end
end
table.insert(bb.trialTrace,string.format(TNd[3724],wpc,vpc-(bb.startT or vpc),xpc,table.concat(zpc,TNd[2497]),Bpc,Apc+Hpc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[wpc-1]or 0,bb.teamDps or 0))
end
if tpc.lastW and tpc.lastW>0 and tpc.lastWT then
table.insert(tpc.waveSec,vpc-tpc.lastWT)
end
if tpc.paidT and wpc>0 and vpc-tpc.paidT<15 then
table.insert(tpc.skip,vpc-tpc.paidT)
end
tpc.paidT=nil
if wpc>0 then
tpc.alive[tostring(wpc)]=bb.hpAliveRaw or 0
end
tpc.lastW,tpc.lastWT=wpc,vpc
end
local Kpc=workspace:FindFirstChild(TNd[3725])
if Kpc and wpc>0 then
tpc.timer[tostring(wpc)]=math.max(tpc.timer[tostring(wpc)]or 0,tonumber(Kpc.Value)or 0)
end
local Lpc=xpc-(bb.lastMoneyR or xpc)
bb.lastMoneyR=xpc
bb.incomeLog=bb.incomeLog or{}
if Lpc>0 then
table.insert(bb.incomeLog,{t=vpc,y=Lpc})
end
while bb.incomeLog[1]and vpc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Mpc=0
for Npc,Opc in ipairs(bb.incomeLog)do
Mpc=Mpc+Opc.y
end
local Ppc=math.min(30,vpc-(bb.startT or vpc))
bb.incomeRate=Ppc>=8 and Mpc/Ppc or nil
for Qpc,Rpc in ipairs(bb.enemies)do
local Spc=Rpc.m
local Tpc=bb.track[Spc]
if not Tpc then
local Upc=Spc._stats
local Vpc=Spc:FindFirstChildOfClass(TNd[3545])
local Wpc=upc.cfgById[Upc.id.Value]
local Xpc=Wpc and fb.baseStats(upc,Wpc)
if Vpc and Xpc and wpc>0 then
local Ypc=Xpc*upc.hpRaw*fb.waveScale(upc,wpc,upc.list[wpc])
if Ypc>0 and Vpc.MaxHealth>0 then
table.insert(tpc.hp,Vpc.MaxHealth/Ypc)
end
end
bb.track[Spc]={t=vpc,p=Rpc.prog,sp=(Upc:FindFirstChild(TNd[3726])and tonumber(Upc.speed.Value))or 1}
if Vpc and Vpc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+Vpc.MaxHealth
end
if wpc>0 then
tpc.spawn[tostring(wpc)]=(tpc.spawn[tostring(wpc)]or 0)+1
tpc.spawnLast[tostring(wpc)]=vpc-(tpc.lastWT or vpc)
end
elseif not Tpc.done and vpc-Tpc.t>=15 then
Tpc.done=true
local Zpc=(Rpc.prog-Tpc.p)/(vpc-Tpc.t)/math.max(0.1,Tpc.sp)
if Zpc>0.001 and Rpc.prog<0.95 then
table.insert(tpc.walk,Zpc)
end
end
end
local _pc=0
for aqc,bqc in ipairs(bb.mine)do
local cqc=bqc._stats:FindFirstChild(TNd[3727])
if cqc then
_pc=_pc+cqc.Value
end
end
tpc.potSum=tpc.potSum or 0
if tpc.lastDealtT then
local dqc=vpc-tpc.lastDealtT
local eqc=0
tpc.potBy=tpc.potBy or{}
for fqc,gqc in ipairs(bb.mine)do
local hqc=gqc._stats
local iqc=hqc.id.Value
if not V.isFarm(iqc)and hqc:FindFirstChild(TNd[3728])and hqc.target.Value~=nil then
local jqc,kqc=pcall(bb.liveDps,gqc,iqc)
if jqc and kqc then
eqc=eqc+kqc*dqc
