local mqc,nqc=pcall(function()
return V.passive(iqc).mark
end)
if mqc and nqc and hqc:FindFirstChild(TNd[1952])then
lqc=lqc+(tonumber(nqc.dot)or 0)*hqc.damage.Value
end
tpc.potBy[iqc]=(tpc.potBy[iqc]or 0)+lqc*dqc
end
end
end
tpc.potWin=(tpc.potWin or 0)+eqc
if vpc-(tpc.winT or vpc)>=5 then
local oqc=_pc-(tpc.winDealt or _pc)
if tpc.potWin>0 and oqc>=0 then
tpc.dealtSum=(tpc.dealtSum or 0)+oqc
tpc.potSum=tpc.potSum+tpc.potWin
end
tpc.winT,tpc.winDealt,tpc.potWin=vpc,_pc,0
end
end
if not tpc.winT then
tpc.winT,tpc.winDealt=vpc,_pc
end
tpc.lastDealtT=vpc
if wpc~=tpc.dpsW and wpc>0 then
tpc.dpsAt[tostring(wpc)]=bb.teamDps or 0
tpc.dpsW=wpc
end
local pqc=math.min(1,vpc-(tpc.densT or vpc))
tpc.densT=vpc
for qqc,rqc in ipairs(bb.enemies)do
