local tqc=workspace._BASES.player:FindFirstChild(TNd[3729])
local uqc=tqc and tqc:FindFirstChild(TNd[3730])
local vqc=uqc and uqc:FindFirstChildOfClass(TNd[3545])
if vqc then
tpc.baseHp=math.max(tpc.baseHp or 0,vqc.MaxHealth)
local wqc=0
for xqc,yqc in ipairs(bb.enemies)do
if yqc.prog>=0.97 then
local zqc=yqc.m:FindFirstChildOfClass(TNd[3545])
wqc=wqc+(zqc and zqc.MaxHealth or yqc.hp)
end
end
if tpc.lastBase and vqc.Health<tpc.lastBase and wqc>0 and tpc.lastBaseT then
table.insert(tpc.baseRel,(tpc.lastBase-vqc.Health)/math.max(0.1,vpc-tpc.lastBaseT)/wqc)
end
tpc.lastBase,tpc.lastBaseT=vqc.Health,vpc
end
end
function bb.recordMap()
local Aqc=bb.mapKey()
local Bqc=P.maps[Aqc]
if Bqc and Bqc.v==1 and Bqc.laneV and(Bqc.densN or 0)==(Bqc.binsDensN or 0)then
return
end
if Bqc and Bqc.v==1 and Bqc.laneV and(Bqc.densN or 0)>5 and(Bqc.binsDensN or 0)>=5 then
return
end
local Cqc={override_hitbox_radius=1.75}
local Dqc={hill_unit=true,override_hitbox_radius=1.75}
local Eqc,Fqc={},false
for Gqc,Hqc in ipairs(bb.cands)do
local Iqc=bb.valid(Hqc,Cqc,true)
if Iqc then
table.insert(Eqc,Iqc)
end
if not Fqc and bb.valid(Hqc,Dqc,true)then
Fqc=true
end
if Gqc%30==0 then
task.wait()
end
end
local Jqc,Kqc={},{}
local Lqc=fb.laneList(bb.samples)
for Mqc=5,60,5 do
local Nqc,Oqc
for Pqc,Qqc in ipairs(Eqc)do
local Rqc=bb.cover(Qqc,Mqc,true)
if not Oqc or Rqc>Oqc then
Nqc,Oqc=Qqc,Rqc
end
end
if Nqc then
local Sqc,Tqc={},{}
for Uqc=1,fb.BINS do
Sqc[Uqc]=TNd[3364]
end
for Vqc,Wqc in ipairs(Lqc or{})do
Tqc[Wqc]={}
for Xqc=1,fb.BINS do
Tqc[Wqc][Xqc]=TNd[3364]
end
end
local Yqc=U.flat(Nqc)
for Zqc,_qc in ipairs(bb.samples)do
if(U.flat(_qc.pos)-Yqc).Magnitude<=Mqc then
local arc=math.min(fb.BINS,math.floor(_qc.prog*fb.BINS)+1)
Sqc[arc]=TNd[1956]
if Tqc[tostring(_qc.lane)]then
Tqc[tostring(_qc.lane)][arc]=TNd[1956]
end
end
end
Jqc[tostring(Mqc)]=table.concat(Sqc)
if Lqc then
Kqc[tostring(Mqc)]={}
for brc,crc in pairs(Tqc)do
Kqc[tostring(Mqc)][brc]=table.concat(crc)
end
end
end
task.wait()
end
local drc=P.maps[Aqc]or{}
P.maps[Aqc]={v=1,laneV=1,bins=Jqc,binsL=Lqc and Kqc or nil,lanes=Lqc,hill=Fqc,spots= #Eqc,dens=drc.dens,densN=drc.densN,binsDensN=drc.densN or 0,lay=drc.lay,walk=drc.walk,walkN=drc.walkN,sep=Lqc and(select(2,pcall(fb.laneSep,bb.samples))or drc.sep)or nil}
fb._masks={}
F.log(1,TNd[3189],string.format(TNd[3731],Aqc,#Eqc,Fqc and TNd[3732]or TNd[3733]))
F.saveSoon()
end
