if Htc and((Htc.stun or 0)>0 or(Htc.slowTime or 0)>0)then
Btc=Btc+1
end
end
local Itc,Jtc=fb.mask(bb.info.map,V.range(ytc.u,0)*(bb.info.rangeScale or 1)),0
for Ktc=1,fb.BINS do
