local Rtc=Qtc and Qtc.stacks and(Qtc.cap or 1)or nil
local Stc,Ttc=pcall(V.range,Ntc.u,0)
Ttc=(Stc and tonumber(Ttc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Utc=Rtc and O.community and tonumber(Otc.time)and tonumber(Otc.cd)
local function Vtc(Wtc,Xtc)
local Ytc=math.floor(Wtc*Otc.time/math.max(1,Otc.cd)+0.001)
return math.min(Rtc,(1+Xtc)^Ytc-1)
end
local Ztc=0
for _tc,auc in ipairs(Ptc)do
local buc=0
for cuc,duc in ipairs(Ptc)do
if(duc.pos-auc.pos).Magnitude<=Ttc then
local euc=Otc.types[duc.base]
local fuc=euc*Otc.uptime
if Utc then
local guc,huc=Vtc(duc.n,euc),duc.n+1
while huc<duc.n+6 and Vtc(huc,euc)<=guc+0.001 do
huc=huc+1
end
fuc=math.max(0,(Vtc(huc,euc)-guc)/(huc-duc.n))
elseif Rtc then
fuc=math.max(0,math.min(Rtc,(duc.n+1)*euc*Otc.uptime)-math.min(Rtc,duc.n*euc*Otc.uptime))
end
buc=buc+duc.dps*fuc
end
end
Ztc=math.max(Ztc,buc)
end
return Ztc*(Utc and 1 or 0.7)
end
