function bb.learn()
local BCc=bb.calRun and bb.calRun.potBy
if type(BCc)~=TNd[1788]then
return
end
pcall(bb.sampleHelpers,true)
local CCc={}
for DCc,ECc in pairs(bb.ownDealt or{})do
if not V.isFarm(ECc.id)then
CCc[ECc.id]=(CCc[ECc.id]or 0)+(tonumber(ECc.v)or 0)
end
end
for FCc,GCc in pairs(bb.helperDealt or{})do
if GCc.owner and V.SUMMONER[GCc.owner]then
CCc[GCc.owner]=(CCc[GCc.owner]or 0)+(tonumber(GCc.v)or 0)
end
end
local HCc,ICc=0,0
for JCc,KCc in pairs(BCc)do
if KCc>0 then
HCc=HCc+(CCc[JCc]or 0)
ICc=ICc+KCc
end
end
if HCc<=0 or ICc<=0 then
return
end
local LCc=HCc/ICc
bb.lastEff={}
for MCc,NCc in pairs(BCc)do
if NCc>0 and NCc/ICc>0.02 then
local OCc=P.learn[MCc]or{eff=1,n=0,v=3}
if(tonumber(OCc.v)or 0)<3 then
OCc.eff,OCc.v=(tonumber(OCc.eff)or 1)*V.effRescale(MCc),3
end
local PCc=math.max(0.02,0.25*math.sqrt(30/(30+OCc.n)))
local QCc=U.clamp(((CCc[MCc]or 0)/NCc)/LCc,0.2,6)
bb.lastEff[MCc]=math.floor(QCc*1000+0.5)/1000
OCc.eff=OCc.eff+(QCc-OCc.eff)*PCc
OCc.n=OCc.n+1
P.learn[MCc]=OCc
end
end
local RCc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if RCc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==TNd[1788]and P.mapLearn or{}
local SCc=type(P.mapLearn[RCc])==TNd[1788]and P.mapLearn[RCc]or{}
for TCc,UCc in pairs(bb.lastEff)do
local VCc=type(SCc[TCc])==TNd[1788]and SCc[TCc]or{eff=UCc,n=0}
local WCc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(VCc.n)or 0))))
VCc.eff=(tonumber(VCc.n)or 0)==0 and UCc or((tonumber(VCc.eff)or UCc)+(UCc-(tonumber(VCc.eff)or UCc))*WCc)
VCc.n=(tonumber(VCc.n)or 0)+1
SCc[TCc]=VCc
