bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(FIc,GIc)
local HIc=(GIc.t or 0)-(FIc.t or 0)
if HIc<bb.BASE_WIN-1 then
return false
end
local IIc=((tonumber(FIc.base)or 0)-(tonumber(GIc.base)or 0))/HIc
if IIc<=0 or(tonumber(GIc.base)or 0)<=0 then
return false
end
local JIc=GIc.base/IIc
local KIc,LIc=0,0
local MIc,NIc=FIc.foes or{},GIc.foes or{}
for OIc,PIc in pairs(NIc)do
if PIc.prog>=bb.BASE_END then
KIc=KIc+PIc.hp
local QIc=MIc[OIc]
if QIc then
LIc=LIc+math.max(0,QIc.hp-PIc.hp)
end
end
end
for RIc,SIc in pairs(MIc)do
if SIc.prog>=bb.BASE_END and not NIc[RIc]then
LIc=LIc+SIc.hp
end
end
if KIc<=0 then
return false
end
local TIc=LIc/HIc
local UIc=TIc>0 and KIc/TIc or math.huge
local VIc={baseTime=JIc,loss=IIc,atEnd=KIc,rate=TIc,killTime=UIc}
return JIc<bb.BASE_SOON and UIc>JIc*bb.BASE_MARGIN,VIc
end
