local wld,xld=sld.obj.AbsoluteSize.Y,uld.AbsoluteWindowSize.Y
if vld<0 then
uld.CanvasPosition=Vector2 .new(0,math.max(0,uld.CanvasPosition.Y+vld-10))
elseif vld+wld>xld then
