function mb.K.key(yld,zld)
local Ald,Bld,Cld=mb.K,mb.Win,Enum.KeyCode
if Ald.cur and not(Ald.cur.obj and Ald.cur.obj.Parent and Ald.shown(Ald.cur.obj))then
Ald.setFocus(nil)
end
if Ald.cur and Ald.cur.listKey and Ald.cur.listKey(yld)then
return true
end
if yld==Cld.PageUp or yld==Cld.PageDown then
local Dld={}
for Eld,Fld in pairs(Bld._tabs)do
table.insert(Dld,{name=Eld,y=Fld.btn.AbsolutePosition.Y,on=Fld.page.Visible})
end
table.sort(Dld,function(Gld,Hld)
return Gld.y<Hld.y
end)
local Ild=1
for Jld,Kld in ipairs(Dld)do
if Kld.on then
Ild=Jld
end
end
Ild=(Ild-1+(yld==Cld.PageDown and 1 or-1))% #Dld+1
Ald.setFocus(nil)
Bld:SelectTab(Dld[Ild].name)
return true
end
if yld==Cld.Tab or yld==Cld.Down or yld==Cld.Up then
local Lld=Ald.order()
if#Lld==0 then
return true
end
local Mld=yld==Cld.Up or(yld==Cld.Tab and zld)
local Nld=table.find(Lld,Ald.cur)
if not Nld then
Nld=Mld and#Lld or 1
else
Nld=(Nld-1+(Mld and-1 or 1))% #Lld+1
end
Ald.setFocus(Lld[Nld])
return true
end
if not Ald.cur then
return false
end
if yld==Cld.Return or yld==Cld.KeypadEnter or yld==Cld.Space then
if Ald.cur.activate then
Ald.cur.activate()
end
return true
end
if yld==Cld.Left or yld==Cld.Right then
if Ald.cur.adjust then
Ald.cur.adjust(yld==Cld.Right and 1 or-1)
end
return true
end
if yld==Cld.Escape then
Ald.setFocus(nil)
return true
end
return false
end
function mb.K.keys(Old)
