return false
end
local Vld=Rld:GetMouseLocation()
local Wld=Sld:GetGuiInset()
local Xld,Yld=Vld.X,Vld.Y-Wld.Y
local Zld,_ld=Uld.AbsolutePosition,Uld.AbsoluteSize
return Xld>=Zld.X and Xld<=Zld.X+_ld.X and Yld>=Zld.Y and Yld<=Zld.Y+_ld.Y
end
Qld:BindActionAtPriority(Pld.keyName,function(amd,bmd,cmd)
