return Enum.ContextActionResult.Pass
end
if Rld:GetFocusedTextBox()or not Pld.over()then
return Enum.ContextActionResult.Pass
end
local dmd,emd=pcall(Pld.key,cmd.KeyCode,Rld:IsKeyDown(Tld.LeftShift)or Rld:IsKeyDown(Tld.RightShift))
return(dmd and emd)and Enum.ContextActionResult.Sink or Enum.ContextActionResult.Pass
end,false,3000,Tld.Tab,Tld.Return,Tld.KeypadEnter,Tld.Space,Tld.Left,Tld.Right,Tld.Up,Tld.Down,Tld.Escape,Tld.PageUp,Tld.PageDown)
Old._track(Rld.InputBegan:Connect(function(fmd)
