if rtd>0 then
mtd=mtd+math.min(1,(tonumber(qtd.have)or 0)/rtd)
ntd=ntd+1
end
end
for std,ttd in ipairs(ltd.items or{})do
if not otd[ttd.id]then
mtd=mtd+1
ntd=ntd+1
end
end
return ntd>0 and mtd/ntd or 0
end
